# ---- tropical water strip + pixel goldfish (own pixel art, feel of pins #08/#11) ----
def q(s): return s.replace('<','%3C').replace('>','%3E').replace('#','%23').replace('"',"'")
FISH=["......ppp.......",
      "....ppllpp......",
      "..ooooooopp...pp",
      ".oyyoooooolp.pll",
      "ooykoooooolpplll",
      "oooooooooolppppl",
      ".ooooooooolp.pll",
      "..oooooool....pp",
      "....pplp........",
      ".....pp........."]
FC={'o':'#F2643A','y':'#FFB36B','k':'#3B1020','p':'#FE8EBE','l':'#FFD3E5'}
_rows=[f[::-1] for f in FISH]
_px=lambda cond:''.join(f'<rect x="{x}" y="{y}" width="1" height="1" fill="{FC[c]}"/>' for y,row in enumerate(_rows) for x,c in enumerate(row) if c!='.' and cond(x))
# tail (x<=3) flips between two frames; whole fish bobs (SMIL, runs inside the background image)
r='<g><animateTransform attributeName="transform" type="translate" values="0 0;0 -0.7;0 0" dur="2.6s" repeatCount="indefinite"/>'+_px(lambda x:x>3)+'<g>'+_px(lambda x:x<=3)+'<animateTransform attributeName="transform" type="translate" values="0 0;0 0.8;0 0;0 -0.6" dur=".9s" calcMode="discrete" repeatCount="indefinite"/></g></g>'

MCB=[".OOOO.","OWW..O","OW...O","O....O","O....O",".OOOO."]
def mcb(px):
    o=''
    for y,row in enumerate(MCB):
        for x,c in enumerate(row):
            X=(x-3)*px;Y=(y-3)*px
            if c=='O': o+=f'<rect x="{X:.2f}" y="{Y:.2f}" width="{px}" height="{px}" fill="#2FA9A3"/>'
            elif c=='W': o+=f'<rect x="{X:.2f}" y="{Y:.2f}" width="{px}" height="{px}" fill="#ffffff"/>'
            elif 0<x<5 and 0<y<5: o+=f'<rect x="{X:.2f}" y="{Y:.2f}" width="{px}" height="{px}" fill="#E9FFFB" fill-opacity=".28"/>'
    return o
def mcbub(x0,y0,x1,y1,d,b,px):
    return f'<g opacity="0"><animateTransform attributeName="transform" type="translate" values="{x0} {y0};{x0+px} {(y0+y1)/2};{x1} {y1}" dur="{d}s" begin="{b}s" repeatCount="indefinite"/><animate attributeName="opacity" values="0;1;1;0" keyTimes="0;.1;.85;1" dur="{d}s" begin="{b}s" repeatCount="indefinite"/>'+mcb(px)+'</g>'
# bubbles rise with SMIL (cheap, no layout); aura is a static radial gradient
bub=''.join(mcbub(cx,9,cx,-5,d,b,.55) for cx,d,b in [(17.5,3.2,0),(19.5,4,1.4),(18.5,3.6,2.4)])
FSVG=q(f'<svg xmlns="http://www.w3.org/2000/svg" viewBox="-1 -6 22 17" shape-rendering="crispEdges">{bub}{r}</svg>')
SHIM=q('<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 96 24" shape-rendering="crispEdges">'+''.join(f'<rect x="{x}" y="{y}" width="2" height="1" fill="#fff"><animate attributeName="opacity" values="0;1;0" dur="{d}s" begin="{b}s" repeatCount="indefinite"/></rect>' for x,y,d,b in [(10,14,2.8,0),(40,18,3.4,1),(70,13,3,1.8),(86,19,2.6,.6),(25,20,3.2,2.2)])+'</svg>')
WAVE=q('<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 64 16" shape-rendering="crispEdges"><path fill="#9FE6D9" d="M0 6h6v-1h6v-1h8v1h6v1h6v1h6v-1h6v-1h8v1h6v1h2V16H0z"/><path fill="#55DECA" d="M0 10h8v-1h8v1h8v1h8v-1h8v-1h8v1h8v1h8V16H0z"/><path fill="#fff" d="M12 4h8v1h-8zM44 5h8v1h-8zM20 9h4v1h-4z"/></svg>')
