WL='<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 96 12" shape-rendering="crispEdges"><g><animateTransform attributeName="transform" type="translate" values="0 0;-48 0" dur="7s" repeatCount="indefinite"/><path fill="#BFF3EA" d="M0 6h8v-2h8v-2h8v2h8v2h8v2h8v-2h8v-2h8v-2h8v2h8v2h8v2h8v-2h8v-2h8v-2h8v2h8v2h8v2h8V12H0z"/><path fill="#fff" opacity=".8" d="M10 3h6v1h-6zM58 1h6v1h-6zM106 3h6v1h-6z"/></g></svg>'
CA='<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 240 120">'+''.join(f'<ellipse cx="{x}" cy="{y}" rx="{rx}" ry="{ry}" fill="#fff" opacity="0"><animate attributeName="opacity" values="0;.22;0" dur="{d}s" begin="{b}s" repeatCount="indefinite"/></ellipse>' for x,y,rx,ry,d,b in [(30,20,22,4,5,0),(110,40,30,5,6,1.5),(190,25,20,3,5.5,3),(70,75,26,4,6.5,2),(170,90,24,4,5,4)])+'</svg>'
BU='<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 300 200" shape-rendering="crispEdges">'+''.join(mcbub(x,215,x+5,-15,d,b,4) for x,d,b in [(30,9,0),(95,11,3),(160,8,5),(230,12,1),(270,10,6.5),(60,10,7.5)])+'</svg>'
FROWS=[f[::-1] for f in FISH]
FPX=''.join(f'<rect x="{x}" y="{y}" width="1" height="1" fill="{FC[c]}"/>' for y,row in enumerate(FROWS) for x,c in enumerate(row) if c!='.')
UF='<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 600 120" shape-rendering="crispEdges"><g><animateTransform attributeName="transform" type="translate" values="-60 60;640 50" dur="34s" repeatCount="indefinite"/><g transform="scale(2.6)"><g><animateTransform attributeName="transform" type="translate" values="0 0;0 -1;0 0" dur="2.6s" repeatCount="indefinite"/>'+FPX+'</g></g></g></svg>'
def L(svg): return 'url("data:image/svg+xml,'+q(svg)+'")'
UW='linear-gradient(180deg,rgba(0,0,0,0) 50%,#BFF3EA 50%,#8FE6DA 68%,#55D3C6 86%,#3FC4BA 100%)'
